// Sends one FINS "Memory Area Read" per entry in READS, same frames as app.py.
// Replies come back on the UDP in node (same local port) and are matched by SID.
const DA1 = 10;   // PLC node
const SA1 = 4;    // this node
const READS = [
    { key: "S1_start", word: 11, bit: 11 },   // STATION_1 Start   W11.11
    { key: "S1_s2",    word: 11, bit: 12 },   // STATION_1 Sensor2 W11.12
    { key: "S2_start", word: 14, bit: 1  },   // STATION_2 Start   W14.01
    { key: "S3_start", word: 11, bit: 0  },   // STATION_3 Start   W11.00
    { key: "S4_start", word: 11, bit: 3  },   // STATION_4 Start   W11.03
    { key: "S5_start", word: 11, bit: 6  },   // STATION_5 Start   W11.06
    { key: "S5_reject", dm: 272 },            // STATION_5 NG count D272 (TOGO_DisplayValue_Judgment_NG)
];
const msgs = READS.map((r, i) => {
    const sid = i + 1;
    const header = Buffer.from([0x80, 0x00, 0x02, 0x00, DA1, 0x00, 0x00, SA1, 0x00, sid]);
    const cmd = Buffer.from([0x01, 0x01]);
    const params = r.dm !== undefined
        ? Buffer.from([0x82, (r.dm >> 8) & 0xff, r.dm & 0xff, 0x00, 0x00, 0x01])            // DM word
        : Buffer.from([0x31, (r.word >> 8) & 0xff, r.word & 0xff, r.bit, 0x00, 0x01]);       // Work bit
    return { payload: Buffer.concat([header, cmd, params]) };
});
return [msgs];

// Stores each FINS reply in flow context "snap" as { v, t } so the logic can use it.
const READS = [
    { key: "S1_start", word: 11, bit: 11 },   // STATION_1 Start   W11.11
    { key: "S1_s2",    word: 11, bit: 12 },   // STATION_1 Sensor2 W11.12
    { key: "S2_start", word: 14, bit: 1  },   // STATION_2 Start   W14.01
    { key: "S3_start", word: 11, bit: 0  },   // STATION_3 Start   W11.00
    { key: "S4_start", word: 11, bit: 3  },   // STATION_4 Start   W11.03
    { key: "S5_start", word: 11, bit: 6  },   // STATION_5 Start   W11.06
    { key: "S5_reject", dm: 272 },            // STATION_5 NG count D272 (TOGO_DisplayValue_Judgment_NG)
];
const d = msg.payload;
if (!Buffer.isBuffer(d) || d.length < 15) return null;
const r = READS[d[9] - 1];              // SID -> which read this answers
if (!r) return null;
if (d[12] !== 0 || d[13] !== 0) {
    node.status({ fill: "red", shape: "dot", text: "FINS error " + d.slice(12, 14).toString("hex") + " on " + r.key });
    return null;
}
let v;
if (r.dm !== undefined) {
    if (d.length < 16) return null;
    v = d.readUInt16BE(14);
} else {
    v = d[14] !== 0;
}
const snap = flow.get("snap") || {};
snap[r.key] = { v: v, t: Date.now() };
flow.set("snap", snap);
return null;

// Same rules as app.py:
//  * Uptime: first JIG at a down station = 1, each further JIG while up = 2, 3, 4 ...
//    Down = no running signal for GRACE_MS; the JIG number then resets.
//  * Start: Uptime 1, then Production 1 PROD_DELAY_MS later (backend needs Uptime first).
//  * Stop:  Production stop packet first, then Uptime 0 PROD_DELAY_MS later.
//  * Count (STATION_5): every JIG sends count "1".
//  * Reject (STATION_5): mirrors D272, sent when it changes.
const GRACE_MS = 180000;          // 3 minutes
const PROD_DELAY_MS = 5000;
const JIG_DEBOUNCE_MS = 1000;     // edges closer than this are the same JIG
const STALE_MS = 2000;            // PLC values older than this = PLC link lost
const API = "http://10.57.10.4:8080/pna/public/api";
const URL = { uptime: API + "/machine_up_time", production: API + "/production",
              count: API + "/machine_count", reject: API + "/machine_reject" };
const PKG = { uptime: "002", production: "003", count: "005", reject: "006" };
const FIELD = { uptime: "uptimeStatus", production: "prodStatus", count: "count", reject: "rejectCount" };
const STATIONS = [
    { code: "STATION_1", start: "S1_start", s2: "S1_s2", debounce: 3000 },  // two sensors, one JIG
    { code: "STATION_2", start: "S2_start" },
    { code: "STATION_3", start: "S3_start" },
    { code: "STATION_4", start: "S4_start" },
    { code: "STATION_5", start: "S5_start", count: true, reject: "S5_reject" },
];

function myt() { return new Date(Date.now() + 8 * 3600 * 1000).toISOString(); }  // Malaysia time
function dtYmd() { const s = myt(); return s.slice(0, 10) + " " + s.slice(11, 19); }
function dtDmy() { const s = myt(); return s.slice(8, 10) + "-" + s.slice(5, 7) + "-" + s.slice(0, 4) + " " + s.slice(11, 19); }

// msg_no sequence per station+signal, restarts at 1 every day (like app.py)
function nextSeq(code, signal) {
    const seq = flow.get("seq") || {};
    const day = dtYmd().slice(0, 10);
    const k = code + ":" + signal;
    if (!seq[k] || seq[k].day !== day) seq[k] = { day: day, n: 0 };
    seq[k].n += 1;
    flow.set("seq", seq);
    return seq[k].n;
}

function post(url, body, meta) {
    meta.body = body;
    meta.retries = 0;
    node.send({ url: url, method: "POST", headers: { "content-type": "application/json" },
                requestTimeout: 5000, payload: body, meta: meta });
}

function send(signal, code, value) {
    const dt = dtYmd();
    const msgNo = code + "/" + PKG[signal] + "_" + dt + "_" + nextSeq(code, signal);
    const data = { datetime: dt, mc_no: code };
    data[FIELD[signal]] = String(value);
    data.package_no = PKG[signal];
    data.msg_no = msgNo;
    post(URL[signal], { data: { data: data } }, { station: code, signal: signal, value: value, msg_no: msgNo });
}

// Production stop: exactly the developer's packet (DD-MM-YYYY, prodStatus as a number, no package_no/msg_no)
function sendStop(code) {
    post(URL.production, { data: { data: { datetime: dtDmy(), mc_no: code, prodStatus: 0 } } },
         { station: code, signal: "production_stop", value: 0 });
}

const now = Date.now();
const snap = flow.get("snap") || {};
const state = flow.get("state") || {};
const fresh = (k) => snap[k] && (now - snap[k].t) < STALE_MS;
let lost = [];

for (const s of STATIONS) {
    const keys = [s.start].concat(s.s2 ? [s.s2] : [], s.reject ? [s.reject] : []);
    if (!keys.every(fresh)) { lost.push(s.code); continue; }
    const st = state[s.code] || (state[s.code] = { value: 0, pendingOff: null, jig: 0, lastRaw: false, lastEdge: -1e15, last: null });
    const trig = snap[s.start].v || (s.s2 ? snap[s.s2].v : false);

    // Up/down with GRACE_MS before calling it down
    let changed = false;
    if (trig) {
        st.pendingOff = null;
        if (st.value !== 1) { st.value = 1; changed = true; }
    } else {
        if (st.value === 1 && st.pendingOff === null) st.pendingOff = now + GRACE_MS;
        if (st.pendingOff !== null && now >= st.pendingOff) {
            st.pendingOff = null;
            if (st.value !== 0) { st.value = 0; changed = true; }
        }
    }

    // One JIG = one rising edge, debounced
    const edge = trig && !st.lastRaw && (now - st.lastEdge) >= (s.debounce || JIG_DEBOUNCE_MS);
    st.lastRaw = trig;
    if (edge) st.lastEdge = now;

    let jigEvent = false;
    if (changed && st.value === 1) { st.jig = 1; jigEvent = true; }
    else if (edge && st.value === 1) { st.jig += 1; jigEvent = true; }
    else if (changed && st.value === 0) { st.jig = 0; }

    if (jigEvent) send("uptime", s.code, st.jig);
    if (changed && st.value === 1) {
        setTimeout(() => send("production", s.code, 1), PROD_DELAY_MS);
    }
    if (changed && st.value === 0) {
        sendStop(s.code);
        setTimeout(() => send("uptime", s.code, 0), PROD_DELAY_MS);
    }
    if (s.count && jigEvent) send("count", s.code, 1);

    // Reject: mirror the PLC's own NG counter. First value after a (re)deploy is only
    // remembered, not sent, so a restart doesn't re-send an already-known count.
    if (s.reject) {
        const v = snap[s.reject].v;
        if (st.last !== null && v !== st.last) send("reject", s.code, v);
        st.last = v;
    }
}
flow.set("state", state);
node.status(lost.length ? { fill: "red", shape: "ring", text: "PLC link lost: " + lost.join(", ") }
                        : { fill: "green", shape: "dot", text: "PLC OK" });
return null;

// Same success rules as app.py:
//  * HTTP 2xx and body "status" == "200" (or no wrapped status)  -> sent
//  * HTTP 2xx but body "status" != "200" -> rejected, NOT retried (backend refused it)
//    Count is the exception: any HTTP 2xx counts as sent.
//  * Network error / timeout / non-2xx -> retried every 5 s, up to MAX_RETRIES, then failed
//    (on a network error the HTTP request node puts the error code, e.g. ECONNREFUSED,
//    in msg.statusCode and the error text in msg.payload)
const MAX_RETRIES = 10;
const m = msg.meta || {};
const http = msg.statusCode;
let result, detail = "";
if (typeof http === "number" && http >= 200 && http < 300) {
    let body = null;
    try { body = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload; } catch (e) {}
    let ok = true;
    if (body && typeof body === "object" && "status" in body) {
        ok = String(body.status) === "200";
        if (!ok) detail = (body.msg || JSON.stringify(body)).toString().slice(0, 200);
    }
    result = ok ? "sent" : (m.signal === "count" ? "sent" : "rejected");
} else {
    detail = typeof http === "number" ? "HTTP " + http : String(msg.payload).slice(0, 200);
    m.retries = (m.retries || 0) + 1;
    if (m.retries < MAX_RETRIES) {
        result = "retrying";
    } else {
        result = "failed";
    }
}
const line = result.toUpperCase() + "  " + m.station + "  " + m.signal + "=" + m.value +
             (typeof http === "number" ? "  http=" + http : "") + (detail ? "  " + detail : "") +
             (result === "retrying" ? "  (try " + m.retries + "/" + MAX_RETRIES + ")" : "");
node.status({ fill: result === "sent" ? "green" : result === "retrying" ? "yellow" : "red", shape: "dot",
              text: line.slice(0, 60) });
const log = { payload: line, result: result, meta: m };
if (result === "retrying") {
    const retry = { url: msg.url, method: "POST", headers: { "content-type": "application/json" },
                    requestTimeout: 5000, payload: m.body, meta: m };
    return [log, retry];
}
return [log, null];
